def fewest_words(text, words):
    vocab = set(words)
    lengths = sorted({len(w) for w in words})
    n = len(text)
    big = n + 1
    best = [0] + [big] * n
    for i in range(1, n + 1):
        b = big
        for L in lengths:
            if L > i:
                break
            if best[i - L] + 1 < b and text[i - L:i] in vocab:
                b = best[i - L] + 1
        best[i] = b
    return best[n] if best[n] < big else -1

